198	    /**
199	     * Resolves and normalizes the owner's address on create, supporting both the structured form
200	     * ({@code addressLine1} / {@code addressLine2}) and the flat {@code address} form kept for
201	     * backward compatibility. Whichever address fields are supplied are normalized (see
202	     * {@link #normalizeAddress(String)}). The structured form is preferred when present: when
203	     * {@code addressLine1} is non-blank the composed {@code address} is the normalized
204	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
205	     * {@code addressLine2} is present; otherwise the composed {@code address} is the normalized flat
206	     * {@code address}. The normalized structured fields are written back so they are stored and
207	     * returned, and the composed value is written to {@code address} so everything that reads the
208	     * address (the household hash, postcode validation and locality) uses the structured fields when
209	     * present, falling back to the flat address. When neither form supplies an address the composed
210	     * {@code address} is blank, so the required-field check rejects it.
211	     *
212	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
213	     */
214	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
215	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
216	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
217	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
218	        String composed;
219	        if (!line1.isEmpty()) {
220	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
221	        } else {
222	            composed = flat;
223	        }
224	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
225	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
226	        ownerFieldsDto.setAddress(composed);
227	    }
