285	    /**
286	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
287	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
288	     *
289	     * @param email the raw email as supplied by the caller, may be {@code null}
290	     * @return the lower-cased email, or {@code null} when none was supplied
291	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
292	     */
293	    private static String normalizeEmail(String email) {
294	        if (email == null || email.isBlank()) {
295	            return null;
296	        }
297	        String trimmed = email.trim();
298	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
299	            throw new InvalidEmailException("Email must be a syntactically valid address");
300	        }
301	        String lowerCased = trimmed.toLowerCase(Locale.ROOT);
302	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
303	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
304	            throw new InvalidEmailException("Email domain is not allowed");
305	        }
306	        return lowerCased;
307	    }
