309	    /**
310	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
311	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
312	     * householdId}, where the email segment is the empty string when the owner has no email. Because
313	     * the telephone is part of the key, two owners that differ in any one segment (for example two
314	     * members of the same household with different telephones) produce different keys.
315	     *
316	     * @param normalizedTelephone the E.164 telephone of the owner
317	     * @param email the lower-cased email of the owner, may be {@code null}
318	     * @param householdId the stable household identifier of the owner, may be {@code null}
319	     * @return the derived identity key
320	     */
321	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
322	        return (normalizedTelephone == null ? "" : normalizedTelephone)
323	            + "|" + (email == null ? "" : email)
324	            + "|" + (householdId == null ? "" : householdId);
325	    }
