347	    /**
348	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
349	     * same computed {@code householdId}, derived from last name and postcode), unless the request
350	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
351	     * block so the owner is created as a declared member of the existing household; without it, a
352	     * second owner in the same household is a conflict.
353	     *
354	     * @param householdId the computed household identifier of the owner being created
355	     * @param sharesHousehold whether the request opted in to sharing an existing household
356	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
357	     */
358	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
359	        if (sharesHousehold) {
360	            return;
361	        }
362	        boolean exists = this.clinicService.findAllOwners().stream()
363	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
364	        if (exists) {
365	            throw new DuplicateHouseholdException(
366	                "An owner with the same last name and postcode already exists");
367	        }
368	    }
