370	    /**
371	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
372	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
373	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
374	     * so there is never a match. When several existing owners qualify the one with the lowest id is
375	     * returned, so the result is deterministic.
376	     *
377	     * @param lastName the last name of the owner being created
378	     * @param postcode the postcode of the owner being created, may be {@code null}
379	     * @param normalizedTelephone the E.164 telephone of the owner being created
380	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
381	     */
382	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
383	        if (postcode == null || postcode.isBlank()) {
384	            return null;
385	        }
386	        String normalizedLastName = normalizeName(lastName);
387	        return this.clinicService.findAllOwners().stream()
388	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
389	            .filter(existing -> postcode.equals(existing.getPostcode()))
390	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
391	            .map(Owner::getId)
392	            .filter(java.util.Objects::nonNull)
393	            .min(Integer::compareTo)
394	            .orElse(null);
395	    }
