397	    /**
398	     * Derives the stable household identifier for an owner from its last name and postcode. The value
399	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
400	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
401	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
402	     * owner with the same last name and postcode is assigned the same identifier automatically, without
403	     * any existing record having to be updated.
404	     *
405	     * @param lastName the last name of the owner being created
406	     * @param postcode the postcode of the owner being created, may be {@code null}
407	     * @return the stable household identifier
408	     */
409	    private static String householdId(String lastName, String postcode) {
410	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
411	        return sha256HexPrefix(key, 12);
412	    }
