473	    /**
474	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
475	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
476	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
477	     * date of the owner being created. The count reflects the state before the new owner is persisted,
478	     * so it excludes the owner being created.
479	     *
480	     * @param registrationDate the effective business-day registration date of the owner being created
481	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
482	     */
483	    private boolean bulkSignupWarning(LocalDate registrationDate) {
484	        long ownersToday = this.clinicService.findAllOwners().stream()
485	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
486	            .count();
487	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
