490	    /**
491	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
492	     * following Monday, any weekday is returned unchanged.
493	     *
494	     * @param date the effective registration date, supplied or defaulted to the server date
495	     * @return the same date when it is a weekday, otherwise the next Monday
496	     */
497	    private static LocalDate toBusinessDay(LocalDate date) {
498	        DayOfWeek dayOfWeek = date.getDayOfWeek();
499	        if (dayOfWeek == DayOfWeek.SATURDAY) {
500	            return date.plusDays(2);
501	        }
502	        if (dayOfWeek == DayOfWeek.SUNDAY) {
503	            return date.plusDays(1);
504	        }
505	        return date;
506	    }
