508	    /**
509	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
510	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
511	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
512	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
513	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
514	     * component: the identity is a pure region-and-hash value.
515	     *
516	     * @param postcode the postcode of the owner being created, may be {@code null}
517	     * @param normalizedTelephone the E.164 telephone of the owner being created
518	     * @param lastName the last name of the owner being created
519	     * @return the formatted customer code
520	     */
521	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
522	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
523	    }
