525	    /**
526	     * De-duplicates a freshly computed customer code against the customer codes already held by
527	     * existing owners. When the code is unused it is returned unchanged; otherwise {@code '-<n>'} is
528	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner carries.
529	     *
530	     * @param customerCode the computed customer code for the owner being created
531	     * @return the same code when unique, otherwise the code with a {@code '-<n>'} suffix that makes
532	     *     it unique
533	     */
534	    private String deduplicateCustomerCode(String customerCode) {
535	        Set<String> existing = new java.util.HashSet<>();
536	        for (Owner owner : this.clinicService.findAllOwners()) {
537	            if (owner.getCustomerCode() != null) {
538	                existing.add(owner.getCustomerCode());
539	            }
540	        }
541	        if (!existing.contains(customerCode)) {
542	            return customerCode;
543	        }
544	        int n = 2;
545	        while (existing.contains(customerCode + "-" + n)) {
546	            n++;
547	        }
548	        return customerCode + "-" + n;
549	    }
