551	    /**
552	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
553	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
554	     * {@code null}, non-numeric, or in no known range.
555	     *
556	     * @param postcode the postcode, may be {@code null}
557	     * @return the region code, or {@code 'UNKNOWN'}
558	     */
559	    private static String regionFromPostcode(String postcode) {
560	        if (postcode == null || postcode.isBlank()) {
561	            return "UNKNOWN";
562	        }
563	        int code;
564	        try {
565	            code = Integer.parseInt(postcode.trim());
566	        } catch (NumberFormatException e) {
567	            return "UNKNOWN";
568	        }
569	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
570	            int[] range = entry.getValue();
571	            if (code >= range[0] && code <= range[1]) {
572	                return entry.getKey();
573	            }
574	        }
575	        return "UNKNOWN";
576	    }
