578	    /**
579	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
580	     * upper-cased.
581	     *
582	     * @param value the string to hash
583	     * @param length the number of leading hex characters to return
584	     * @return the upper-cased hex prefix of the digest
585	     */
586	    private static String sha256HexPrefix(String value, int length) {
587	        try {
588	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
589	            StringBuilder sb = new StringBuilder(digest.length * 2);
590	            for (byte b : digest) {
591	                sb.append(String.format("%02x", b));
592	            }
593	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
594	        } catch (NoSuchAlgorithmException e) {
595	            throw new IllegalStateException("SHA-256 not available", e);
596	        }
597	    }
