624	     *
625	     * @param householdId the stable household identifier of the owner being created
626	     * @return the number of household members after this create (always at least 1)
627	     */
628	    private int householdSize(String householdId) {
629	        if (householdId == null) {
630	            return 1;
631	        }
632	        return (int) this.clinicService.findAllOwners().stream()
633	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
634	            .count() + 1;
635	    }
636	
637	    /**
638	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
639	     * lower-casing.
640	     *
641	     * @param value the raw name, may be {@code null}
642	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
643	     */
644	    private static String normalizeName(String value) {
645	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
646	    }
647	
648	    /**
649	     * The fixed city-to-region table used to validate a postcode against its city
650	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
651	     * therefore accepts any 4-digit postcode.
652	     */
653	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
654	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
655	
656	    /**
657	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
658	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
659	     */
660	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
661	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
662	
663	    /**
664	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
665	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
666	     * when the city maps to a known region, must fall within that region's inclusive range
667	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
668	     * postcode.
669	     *
670	     * @param city the city of the owner being created
671	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
672	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
673	     *     for the city's region
674	     */
675	    private static void validatePostcode(String city, String postcode) {
676	        if (postcode == null || postcode.isBlank()) {
677	            return;
678	        }
679	        if (!postcode.matches("\\d{4}")) {
680	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
681	        }
682	        String region = CITY_REGION.get(city);
683	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
684	        if (range != null) {
685	            int value = Integer.parseInt(postcode);
686	            if (value < range[0] || value > range[1]) {
687	                throw new InvalidPostcodeException(
688	                    "Postcode is out of range for the city's region");
689	            }
690	        }
691	    }
692	
693	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
694	    @Override
695	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
696	        Owner owner = this.clinicService.findOwnerById(ownerId);
697	        if (owner == null) {
698	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
699	        }
700	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
701	    }
702	
703	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
704	    @Override
705	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
706	        applyAddress(ownerFieldsDto);
707	        validateRequiredFields(ownerFieldsDto);
708	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
709	        if (registrationDate == null) {
710	            registrationDate = LocalDate.now();
711	        } else if (registrationDate.isAfter(LocalDate.now())) {
712	            throw new FutureRegistrationDateException(
713	                "registrationDate must not be later than the server date");
714	        }
715	        registrationDate = toBusinessDay(registrationDate);
716	        ownerFieldsDto.setRegistrationDate(registrationDate);
717	        rejectDailyOwnerLimit(registrationDate);
718	        rejectCityAtCapacity(ownerFieldsDto.getCity());
719	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
720	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
721	        ownerFieldsDto.setTelephone(normalizedTelephone);
722	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
723	        ownerFieldsDto.setEmail(normalizedEmail);
724	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
725	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
726	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
727	        rejectDuplicateHousehold(ownerHouseholdId, sharesHousehold);
728	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
729	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
730	        HttpHeaders headers = new HttpHeaders();
731	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
732	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
733	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
734	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(
735	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName())));
736	        owner.setHouseholdId(ownerHouseholdId);
737	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
738	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
739	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
740	        this.clinicService.saveOwner(owner);
741	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
742	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
743	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
744	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
745	        headers.setLocation(UriComponentsBuilder.newInstance()
746	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
747	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
748	    }
749	
750	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
751	    @Override
752	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
753	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
754	        if (currentOwner == null) {
755	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	        }
757	        currentOwner.setAddress(ownerFieldsDto.getAddress());
758	        currentOwner.setCity(ownerFieldsDto.getCity());
759	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
760	        currentOwner.setLastName(ownerFieldsDto.getLastName());
761	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
762	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
763	        this.clinicService.saveOwner(currentOwner);
764	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
765	    }
766	
767	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
