33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's {@code ageBand} from its birthDate relative to the registrationDate:
39	     * {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and {@code SENIOR} when 65 or older.
40	     * Returns {@code null} when the owner has no birthDate or no registrationDate.
41	     */
42	    default OwnerDto.@Nullable AgeBandEnum ageBand(@Nullable Owner owner) {
43	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
44	            return null;
45	        }
46	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
47	        if (age < 18) {
48	            return OwnerDto.AgeBandEnum.MINOR;
49	        }
50	        if (age < 65) {
51	            return OwnerDto.AgeBandEnum.ADULT;
52	        }
53	        return OwnerDto.AgeBandEnum.SENIOR;
54	    }
55	
56	    /**
57	     * Derives the owner's duplicate-detection {@code identityKey}, formatted as
58	     * {@code normalizedTelephone + '|' + email + '|' + householdId} with an empty email segment when
59	     * the owner has no email. This is the same key the create endpoint uses to reject an owner whose
60	     * whole key equals an existing owner's.
61	     */
62	    default @Nullable String identityKey(@Nullable Owner owner) {
63	        if (owner == null) {
64	            return null;
65	        }
66	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
67	        String email = owner.getEmail() == null ? "" : owner.getEmail();
68	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
69	        return telephone + "|" + email + "|" + householdId;
70	    }
71	
72	    /**
73	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
74	     * otherwise {@code PHONE}.
75	     */
76	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
77	        if (owner == null) {
